/**
 * Cross-checks against independent SciPy / NumPy results stored in tests/fixtures/scipy.json
 * (generated by scripts/scipy_crosscheck.py). Skipped when the fixture is missing.
 */
import assert from 'node:assert/strict'
import { existsSync, readFileSync } from 'node:fs'
import { describe, it } from 'node:test'
import { simulateEpidemic } from '../src/numerics/epidemic.ts'
import { designFir, fft, windowFn } from '../src/numerics/fft.ts'
import { onsagerEnergy } from '../src/numerics/ising.ts'
import { backwardEulerAdaptive, dopri45 } from '../src/numerics/ode.ts'
import { kepler, lorenz, robertson, vanDerPol } from '../src/numerics/systems.ts'

const path = new URL('./fixtures/scipy.json', import.meta.url)
const fx = existsSync(path) ? JSON.parse(readFileSync(path, 'utf8')) : null
const maxDiff = (a: ArrayLike<number>, b: ArrayLike<number>) => Math.max(...Array.from(a, (v, i) => Math.abs(v - b[i])))

describe(`SciPy cross-check${fx ? ` (${fx.generator})` : ''}`, { skip: !fx && 'fixture missing — run `npm run crosscheck`' }, () => {
  it('Dormand–Prince agrees with SciPy DOP853 on Lorenz, Van der Pol and Kepler (e = 0.9)', (t) => {
    const cases: [string, ReturnType<typeof lorenz>, number[], number, number[]][] = [
      ['Lorenz t=2', lorenz(), [1, 1, 1], 2, fx.lorenz_t2],
      ['Van der Pol μ=10 t=20', vanDerPol(10), [2, 0], 20, fx.vdp10_t20],
      ['Kepler e=0.9 t=3', kepler(0.9), Array.from(kepler(0.9).y0), 3, fx.kepler09_t3],
    ]
    for (const [name, p, y0, T, ref] of cases) {
      const r = dopri45(p, 0, y0, T, { rtol: 1e-12, atol: 1e-12, record: false })
      const d = maxDiff(r.yEnd, ref)
      t.diagnostic(`${name}: max |Δ| = ${d.toExponential(2)}`)
      assert.ok(d < 1e-8)
    }
  })

  it('our RK45 step-size controller takes a similar number of steps to SciPy RK45', (t) => {
    const k = kepler(0.6)
    const r = dopri45(k, 0, k.y0, 2 * Math.PI, { rtol: 1e-8, atol: 1e-8, record: false })
    t.diagnostic(`ours ${r.accepted} accepted steps, SciPy ${fx.rk45_kepler06_steps}`)
    assert.ok(Math.abs(r.accepted - fx.rk45_kepler06_steps) / fx.rk45_kepler06_steps < 0.3)
  })

  it('adaptive backward Euler agrees with SciPy Radau on Robertson at t = 40', (t) => {
    const p = robertson()
    const r = backwardEulerAdaptive(p, 0, p.y0, 40, { rtol: 1e-5, atol: 1e-10, record: false })
    const rel = Array.from(r.yEnd, (v, i) => Math.abs(v - fx.robertson_t40[i]) / fx.robertson_t40[i])
    t.diagnostic(`relative differences ${rel.map((v) => v.toExponential(2)).join(', ')}`)
    rel.forEach((v) => assert.ok(v < 2e-3))
  })

  it('SIR (RK4, h = 0.1 day) agrees with SciPy DOP853 at day 100', () => {
    const s = simulateEpidemic('SIR', { beta: 0.3, gamma: 0.1, sigma: 0, N: 1e6, I0: 10 }, 100)
    const ours = [s.S[100], s.I[100], s.R[100]]
    ours.forEach((v, i) => assert.ok(Math.abs(v - fx.sir_day100[i]) / fx.sir_day100[i] < 1e-6))
  })

  it('FFT agrees with numpy.fft.fft', () => {
    const re = Float64Array.from(fx.fft64_input as number[])
    const im = new Float64Array(re.length)
    fft(re, im)
    assert.ok(maxDiff(re, fx.fft64_re) < 1e-12)
    assert.ok(maxDiff(im, fx.fft64_im) < 1e-12)
  })

  it('windows and windowed-sinc FIR agree with scipy.signal', () => {
    assert.ok(maxDiff(windowFn('hann', 16), fx.hann16) < 1e-15)
    assert.ok(maxDiff(windowFn('blackman', 16), fx.blackman16) < 1e-15)
    assert.ok(maxDiff(designFir('lowpass', 101, 1000, 100, 100, 'blackman'), fx.firwin_lowpass_101_100Hz_fs1000_blackman) < 1e-12)
  })

  it("Onsager energy (AGM elliptic integral) agrees with scipy.special.ellipk", () => {
    ;(fx.onsager_T as number[]).forEach((T, i) => assert.ok(Math.abs(onsagerEnergy(T) - fx.onsager_energy[i]) < 1e-12))
  })
})
